import java.util.*;
import java.io.*;

public class Main {
    static final int mod = 1000000007;
    static final int inv = 570000004;

    static int add(int a, int b) {
        return a + b < mod ? a + b : a + b - mod;
    }

    static int sub(int a, int b) {
        return a < b ? a - b + mod : a - b;
    }

    static int mul(int a, int b) {
        return (int)((long)a * b % mod);
    }

    static class U128 {
        BitSet bits = new BitSet(128);

        U128() {
        }

        U128(BitSet bs) {
            this.bits = (BitSet) bs.clone();
        }

        public boolean get(int index) {
            return bits.get(index);
        }

        public void set(int index, boolean value) {
            bits.set(index, value);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof U128)) return false;
            U128 u128 = (U128) o;
            return bits.equals(u128.bits);
        }

        @Override
        public int hashCode() {
            return bits.hashCode();
        }
    }

    static Map<U128, Integer> name = new HashMap<>();
    static int n, dfn = 0;
    static int[][] son;
    static Map<U128, Integer> memo = new HashMap<>();

    static int dfs(U128 s) {
        if (name.containsKey(s)) return name.get(s);
        int ret = dfn++;
        name.put(s, ret);
        int size = 1 << n;
        son[ret] = new int[size];
        for (int i = 0; i < size; i++) {
            U128 t = new U128(s.bits);
            for (int j = 0; j < size; j++) {
                if (!t.get(j)) {
                    for (int k = i & j; k != 0; k ^= k & -k) {
                        if (s.get(j ^ (k & -k))) {
                            t.set(j, true);
                            break;
                        }
                    }
                }
            }
            son[ret][i] = dfs(t);
        }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        n = Integer.parseInt(br.readLine());
        int maxState = 1 << n;
        son = new int[65536][];
        U128 initial = new U128();
        initial.bits.set(0); // set first bit to represent starting state

        dfs(initial);

        int[][] p = new int[n][n];
        int[][] q = new int[n][maxState];
        int[][] dp = new int[n + 1][65536];

        // Read matrix p
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                p[i][j] = Integer.parseInt(st.nextToken());
                p[i][j] = mul(p[i][j], inv);
            }
        }

        // Compute q
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < maxState; j++) {
                q[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    int pValue = p[k][i];
                    if (((j >> k) & 1) != 0) {
                        q[i][j] = mul(q[i][j], pValue);
                    } else {
                        q[i][j] = mul(q[i][j], sub(1, pValue));
                    }
                }
            }
        }

        dp[0][0] = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < dfn; j++) {
                int[] sonArr = son[j];
                for (int k = 0; k < maxState; k++) {
                    int sIndex = sonArr[k];
                    dp[i + 1][sIndex] = add(dp[i + 1][sIndex], mul(dp[i][j], q[i][k]));
                }
            }
        }

        U128 resState = new U128();
        resState.bits.set(0, true);
        int finalStateIndex = name.get(resState);
        System.out.println(dp[n][finalStateIndex]);
    }
}
